{"content":""""Classify /app/documents files as invoice/other, move them, extract amounts, write summary.csv."""
import csv
import os
import re
import shutil
import subprocess

SRC = "/app/documents"
INV_DIR = "/app/invoices"
OTH_DIR = "/app/other"
os.makedirs(INV_DIR, exist_ok=True)
os.makedirs(OTH_DIR, exist_ok=True)


def pdf_text(path):
    from pypdf import PdfReader
    r = PdfReader(path)
    return "\n".join((p.extract_text() or "") for p in r.pages)


def ocr_text(path):
    out = subprocess.run(["tesseract", path, "stdout"],
                         capture_output=True, text=True, timeout=300)
    return out.stdout


def get_text(path):
    if path.lower().endswith(".pdf"):
        return pdf_text(path)
    return ocr_text(path)


def parse_eu(num):
    """'6 860,45' -> 6860.45 ; '623,68' -> 623.68"""
    return float(num.replace(" ", "").replace(",", "."))


def parse_us(num):
    return float(num.replace(",", ""))


def extract_us_invoice(text):
    """'Total: $X' + 'Amount due: $Y' -> use Total per rule. No VAT -> 0."""
    m = re.search(r"Total:\s*\$([\d,]+(?:\.\d+)?)", text)
    assert m, "US invoice Total not found"
    return parse_us(m.group(1)), 0.0


def extract_eu_invoice(text):
    """Summary '$ net $ vat $ gross' -> total=last, vat=second-to-last."""
    amounts = re.findall(r"\$\s*([\d][\d\s]*,\d{2})", text)
    assert len(amounts) >= 2, f"expected summary $-amounts, got {amounts}"
    vat = parse_eu(amounts[-2])
    total = parse_eu(amounts[-1])
    return total, vat


def extract_northwind(text):
    m = re.search(r"TotalPrice\s*([\d.]+)", text)
    assert m, "TotalPrice not found"
    return float(m.group(1)), 0.0


files = sorted(os.listdir(SRC))
results = {}   # filename -> (text, kind)
for f in files:
    path = os.path.join(SRC, f)
    if not os.path.isfile(path):
        continue
    results[f] = get_text(path)

# --- classification: invoice iff the word 'invoice' appears in content ---
kinds = {}
for f, text in results.items():
    kinds[f] = "invoice" if re.search(r"\binvoice\b", text, re.I) else "other"

print("Classification:")
for f in sorted(kinds):
    print(f"  {f}: {kinds[f]}")

# sanity: expected split 10 invoices / 7 other
n_inv = sum(1 for k in kinds.values() if k == "invoice")
print(f"invoices={n_inv} other={len(kinds) - n_inv}")

invoice_rows = []
for f in sorted(kinds):
    text = results[f]
    kind = kinds[f]
    if kind == "invoice":
        if re.search(r"TotalPrice", text):
            total, vat = extract_northwind(text)
        elif re.search(r"Amount due", text):
            total, vat = extract_us_invoice(text)
        elif "$" in text and re.search(r",\d{2}", text):
            total, vat = extract_eu_invoice(text)
        else:
            raise ValueError(f"No extractor matched invoice {f}")
        print(f"  {f}: total={total} vat={vat}")
        invoice_rows.append((f, total, vat))
        shutil.move(os.path.join(SRC, f), os.path.join(INV_DIR, f))
    else:
        assert not re.search(r"TotalPrice|Amount due|INVOICE|Invoice no", text), \
            f"other-doc {f} looks like an invoice!"
        shutil.move(os.path.join(SRC, f), os.path.join(OTH_DIR, f))

sum_total = round(sum(t for _, t, _ in invoice_rows), 2)
sum_vat = round(sum(v for _, _, v in invoice_rows), 2)

with open(os.path.join(INV_DIR, "summary.csv"), "w", newline="") as fh:
    w = csv.writer(fh)
    w.writerow(["filename", "total_amount", "vat_amount"])
    for f, t, v in invoice_rows:
        w.writerow([f, f"{t:.2f}", f"{v:.2f}"])
    w.writerow(["total", f"{sum_total:.2f}", f"{sum_vat:.2f}"])

print(f"SUM total={sum_total:.2f} vat={sum_vat:.2f}")
print("remaining in documents:", os.listdir(SRC))
","path":"/tmp/process_docs.py"}
